def cmp_semver(a, b):
    # Strip build metadata entirely (everything after '+')
    a = a.split('+', 1)[0]
    b = b.split('+', 1)[0]

    # Separate main version from pre-release identifier
    a_main, _, a_pre = a.partition('-')
    b_main, _, b_pre = b.partition('-')

    # Compare numeric major.minor.patch components
    a_nums = [int(x) for x in a_main.split('.')]
    b_nums = [int(x) for x in b_main.split('.')]
    for an, bn in zip(a_nums, b_nums):
        if an < bn:
            return -1
        if an > bn:
            return 1

    # A pre-release version sorts before its release counterpart
    has_a = bool(a_pre)
    has_b = bool(b_pre)
    if not has_a and not has_b:
        return 0
    if has_a and not has_b:
        return -1
    if not has_a and has_b:
        return 1

    # Both have pre-release identifiers; compare left to right
    a_ids = a_pre.split('.')
    b_ids = b_pre.split('.')
    for aid, bid in zip(a_ids, b_ids):
        res = _cmp_pre_id(aid, bid)
        if res != 0:
            return res

    # All preceding identifiers equal; the longer list wins
    if len(a_ids) < len(b_ids):
        return -1
    if len(a_ids) > len(b_ids):
        return 1
    return 0


def _cmp_pre_id(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()

    if a_num and b_num:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_num:  # numeric identifiers sort before alphanumeric ones
        return -1
    if b_num:
        return 1
    # both alphanumeric: ASCII lexical order
    return (a > b) - (a < b)
```

