import re


def gitignore_match(pattern, path):
    if not pattern:
        return False

    pat = pattern.rstrip('/')
    dir_only = len(pat) < len(pattern)

    leading_slash = pat.startswith('/')
    has_middle_slash = '/' in pat
    anchored = leading_slash or has_middle_slash

    while pat.startswith('/'):
        pat = pat[1:]

    is_dir = path.endswith('/')
    core = path[:-1] if is_dir else path

    out = []
    if not anchored:
        out.append('(?:[^/]+/)*')

    i, n = 0, len(pat)
    while i < n:
        c = pat[i]
        if c == '*':
            if i + 1 < n and pat[i + 1] == '*':
                if i + 2 < n and pat[i + 2] == '/':
                    out.append('(?:[^/]*/)*')
                    i += 3
                elif i + 2 == n:
                    out.append('.*')
                    i += 2
                else:
                    out.append('[^/]*')
                    i += 2
            else:
                out.append('[^/]*')
                i += 1
        elif c == '/':
            if i + 3 == n and pat[i + 1:i + 3] == '**':
                out.append('/.*')
                i += 3
            else:
                out.append('/')
                i += 1
        elif c == '?':
            out.append('[^/]')
            i += 1
        elif c == '[':
            k = i + 1
            negated = False
            if k < n and pat[k] == '!':
                negated = True
                k += 1
            chars = []
            if k < n and pat[k] == ']':
                chars.append(']')
                k += 1
            while k < n and pat[k] != ']':
                ch = pat[k]
                if ch == '\\' and k + 1 < n:
                    chars.append('\\' + pat[k + 1])
                    k += 2
                else:
                    chars.append(ch)
                    k += 1
            if k < n and pat[k] == ']':
                out.append('[' + ('^' if negated else '') + ''.join(chars) + ']')
                i = k + 1
            else:
                out.append('\\[')
                i += 1
        elif c == '\\':
            if i + 1 < n:
                out.append(pat[i + 1])
                i += 2
            else:
                out.append('\\\\')
                i += 1
        else:
            if c in '^$+(){}|.':
                out.append('\\' + c)
            else:
                out.append(c)
            i += 1

    regex = ''.join(out)
    matched = re.fullmatch(regex, core) is not None
    if dir_only:
        return is_dir and matched
    return matched
