def parse_range(header, size):
    if header is None or size < 0:
        return None

    h = header.strip()
    if not h.lower().startswith('bytes='):
        return None
    spec = h[6:]

    ranges = []
    for part in spec.split(','):
        part = part.strip()
        if not part or '-' not in part:
            return None

        start_str, end_str = (p.strip() for p in part.split('-', 1))
        if start_str == '' and end_str == '':
            return None

        if start_str == '':
            # suffix range -> last n bytes
            try:
                n = int(end_str)
            except ValueError:
                return None
            if n < 0:
                return None
            start, end = (0, size - 1) if n >= size else (size - n, size - 1)
        else:
            try:
                start = int(start_str)
            except ValueError:
                return None
            if start < 0:
                return None
            if end_str == '':
                end = size - 1
            else:
                try:
                    end = int(end_str)
                except ValueError:
                    return None
                if end < start:
                    return None          # malformed: end before start
                if end > size - 1:
                    end = size - 1       # clamp to last byte

        if start > end or start >= size:
            continue                     # unsatisfiable -> drop (or all -> None)
        ranges.append((start, end))

    return ranges or None
```

