def damerau(a, b):
    n = len(a)
    m = len(b)
    maxdist = n + m

    # array index p represents logical index p-1; row/col 0 are -1 sentinels (=maxdist)
    d = [[maxdist] * (m + 2) for _ in range(n + 2)]

    d[1][1] = 0
    for i in range(1, n + 1):
        d[i + 1][1] = i
    for j in range(1, m + 1):
        d[1][j + 1] = j

    da = {}
    for i in range(1, n + 1):
        db = 0
        for j in range(1, m + 1):
            k = da.get(b[j - 1], -1)   # last position in a of char b[j]; -1 if none
            l = db                    # last position in b of char a[i]

            if a[i - 1] == b[j - 1]:
                cost = 0
                db = j
            else:
                cost = 1

            best = min(
                d[i][j] + cost,          # substitution   (logical i-1, j-1)
                d[i + 1][j] + 1,         # insertion      (logical i,   j-1)
                d[i][j + 1] + 1,         # deletion       (logical i-1, j)
            )

            if k != -1:
                t = d[k][l] + (i - k - 1) + 1 + (j - l - 1)  # transposition (logical k-1, l-1)
                if t < best:
                    best = t

            d[i + 1][j + 1] = best

    return d[n + 1][m + 1]
