import heapq


def topk(stream, k):
    if k <= 0:
        return []
    heap = []
    for i, item in enumerate(stream):
        value, label = item
        entry = (value, -i, label)
        if len(heap) < k:
            heapq.heappush(heap, entry)
        elif value > heap[0][0]:
            heapq.heapreplace(heap, entry)
    ordered = sorted(heap, key=lambda e: (-e[0], -e[1]))
    return [(value, label) for value, _neg_i, label in ordered]
