def parse_duration(s):
    if not isinstance(s, str) or s == '':
        raise ValueError("duration must be a non-empty string")

    text = s
    negative = False
    if text[0] == '-':
        negative = True
        text = text[1:]
    elif text[0] == '+':
        text = text[1:]

    if not text.startswith('P'):
        raise ValueError("invalid duration: must start with P")

    body = text[1:]

    if 'T' in body:
        date_part, _, time_part = body.partition('T')
    else:
        date_part = body
        time_part = None

    def parse_part(part, units):
        result = {}
        if part == '':
            return result
        i = 0
        n = len(part)
        last_idx = -1
        while i < n:
            j = i
            while j < n and (part[j].isdigit() or part[j] == '.'):
                j += 1
            if j == i:
                raise ValueError("invalid duration")
            num = float(part[i:j])
            if j >= n or part[j] not in units:
                raise ValueError("invalid duration")
            idx = units.index(part[j])
            if idx <= last_idx:
                raise ValueError("duration field out of order or duplicated")
            result[part[j]] = num
            last_idx = idx
            i = j + 1
        return result

    years_data = parse_part(date_part, ['Y', 'M', 'D'])

    if time_part is not None:
        if time_part == '':
            raise ValueError("T present but no time fields")
        time_data = parse_part(time_part, ['H', 'M', 'S'])
    else:
        time_data = {}

    if not years_data and not time_data:
        raise ValueError("no duration fields present")

    total_days = (years_data.get('Y', 0.0) * 365.0
                  + years_data.get('M', 0.0) * 30.0
                  + years_data.get('D', 0.0))

    seconds = (total_days * 86400.0
               + time_data.get('H', 0.0) * 3600.0
               + time_data.get('M', 0.0) * 60.0
               + time_data.get('S', 0.0))

    if negative:
        seconds = -seconds

    return float(seconds)
