class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.num_components = n
        self.history = []  # stack of undo records for successful unions

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        # Union by size: attach smaller tree under larger tree's root.
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        # Record enough to undo this single-pointer / single-size change.
        self.history.append((rb, self.parent[rb], ra, self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.num_components -= 1
        return True

    def snapshot(self):
        # Token is the current length of the undo history.
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            rb, old_parent_rb, ra, old_size_ra = self.history.pop()
            self.parent[rb] = old_parent_rb
            self.size[ra] = old_size_ra
            self.num_components += 1

    def components(self):
        return self.num_components
