    def add(self, word):
        node = self._root
        for ch in word:
            nxt = node.get(ch)
            if nxt is None:
                nxt = {}
                node[ch] = nxt
            node = nxt
        node['#'] = node.get('#', 0) + 1

    def remove(self, word):
        node = self._root
        path = []
        for ch in word:
            child = node.get(ch)
            if child is None:
                return False
            path.append((node, ch))
            node = child
        count = node.get('#', 0)
        if count == 0:
            return False
        if count == 1:
            del node['#']
            for parent, ch in reversed(path):
                c = parent[ch]
                if not c:  # no children and no word marker left
                    del parent[ch]
                else:
                    break
        else:
            node['#'] = count - 1
        return True

    def search(self, pattern):
        result = []
        self._match(self._root, pattern, 0, [], result)
        result.sort()
        return result

    def _match(self, node, pattern, i, prefix, result):
        if i == len(pattern):
            if node.get('#', 0):
                result.append(''.join(prefix))
            return
        ch = pattern[i]
        if ch == '.':
            for c, child in node.items():
                if c == '#':
                    continue
                prefix.append(c)
                self._match(child, pattern, i + 1, prefix, result)
                prefix.pop()
        else:
            child = node.get(ch)
            if child is not None:
                prefix.append(ch)
                self._match(child, pattern, i + 1, prefix, result)
                prefix.pop()
