def to_base(n, alphabet):
    if not alphabet:
        raise ValueError("alphabet must be non-empty")
    base = len(alphabet)
    if n == 0:
        return alphabet[0]
    negative = n < 0
    digits = []
    while n:
        n, rem = divmod(abs(n), base)
        digits.append(alphabet[rem])
    if negative:
        digits.append('-')
    return ''.join(reversed(digits))


def from_base(s, alphabet):
    if not s:
        raise ValueError("string must be non-empty")
    index = {c: i for i, c in enumerate(alphabet)}
    negative = False
    rest = s
    if s[0] == '-':
        negative = True
        rest = s[1:]
    if not rest:
        raise ValueError("string must be non-empty")
    base = len(alphabet)
    result = 0
    for ch in rest:
        if ch not in index:
            raise ValueError(f"character '{ch}' not in alphabet")
        result = result * base + index[ch]
    return -result if negative else result
