import heapq
from collections import deque


def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    INF = float('inf')

    # Dijkstra for minimum cost (heap-based).
    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, INF):
            continue
        for v, w in graph[u]:
            nd = d + w
            if nd < dist.get(v, INF):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))

    if dst not in dist:
        return (None, [])

    # Reverse BFS over shortest-path DAG edges to compute hopdist[v]:
    # minimum number of edges from v to dst along a minimum-cost path.
    rev = {}
    for u, neighbours in graph.items():
        du = dist.get(u, INF)
        if du == INF:
            continue
        for v, w in neighbours:
            if du + w == dist.get(v, INF):
                rev.setdefault(v, []).append(u)

    hopdist = {dst: 0}
    dq = deque([dst])
    while dq:
        x = dq.popleft()
        nxt = hopdist[x] + 1
        for y in rev.get(x, ()):
            if y not in hopdist:
                hopdist[y] = nxt
                dq.append(y)

    if src not in hopdist:
        return (None, [])

    # Greedily build the lexicographically smallest min-cost, min-hop path.
    path = [src]
    cur = src
    while cur != dst:
        target = hopdist[cur] - 1
        best = None
        for v, w in graph[cur]:
            if dist.get(cur, INF) + w == dist.get(v, INF) \
                    and hopdist.get(v) is not None and hopdist[v] == target:
                if best is None or v < best:
                    best = v
        path.append(best)
        cur = best

    return (dist[dst], path)
