import re


class Spreadsheet:
    def __init__(self):
        self._formula = {}     # cell -> AST node | ('num', value)
        self._deps = {}        # cell -> set of direct dependency cells
        self._dependents = {}  # cell -> set of cells referencing this cell
        self._value = {}       # cell -> current computed value

    def set(self, cell, value):
        cell = cell.upper()
        if isinstance(value, str) and value.startswith('='):
            ast = self._parse_formula(value)
            refs = self._collect_refs(ast)
        else:
            ast = ('num', self._coerce_number(value))
            refs = []

        if self._creates_cycle(cell, refs):
            raise ValueError("reference cycle detected")

        for d in list(self._deps.get(cell, ())):
            grp = self._dependents.get(d)
            if grp is not None:
                grp.discard(cell)
                if not grp:
                    del self._dependents[d]

        self._formula[cell] = ast
        self._deps[cell] = set(refs)
        for r in refs:
            self._dependents.setdefault(r, set()).add(cell)

        new_val = self._eval_node(ast)
        old_val = self._value.get(cell, 0)
        self._value[cell] = new_val

        if new_val != old_val:
            stack = list(self._dependents.get(cell, ()))
            while stack:
                cur = stack.pop()
                nv = self._eval_node(self._formula[cur])
                ov = self._value.get(cur, 0)
                if nv != ov:
                    self._value[cur] = nv
                    grp = self._dependents.get(cur)
                    if grp:
                        for d in grp:
                            stack.append(d)

    def get(self, cell):
        return self._value.get(cell.upper(), 0)

    # ---- helpers ----
    @staticmethod
    def _coerce_number(value):
        if isinstance(value, (int, float)):
            return value
        if isinstance(value, str):
            s = value.strip()
            try:
                return int(s)
            except ValueError:
                return float(s)
        raise ValueError("unsupported value type")

    def _collect_refs(self, node):
        refs = []
        stack = [node]
        while stack:
            nd = stack.pop()
            tag = nd[0]
            if tag == 'num':
                continue
            if tag == 'cell':
                refs.append(nd[1])
            else:
                stack.append(nd[1])
                stack.append(nd[2])
        return refs

    def _eval_node(self, node):
        tag = node[0]
        if tag == 'num':
            return node[1]
        if tag == 'cell':
            return self._value.get(node[1], 0)
        left = self._eval_node(node[1])
        right = self._eval_node(node[2])
        if tag == '+':
            return left + right
        if tag == '-':
            return left - right
        if tag == '*':
            return left * right
        raise ValueError("invalid operator")

    def _creates_cycle(self, cell, refs):
        if cell in refs:
            return True
        for r in refs:
            seen = set()
            st = [r]
