function pLimit(concurrency) {
	concurrency = (Number.isInteger(concurrency) || concurrency === Infinity) && concurrency > 0 ? concurrency : 1;

	let activeCount = 0;
	const queue = [];

	function startNext() {
		if (activeCount >= concurrency || queue.length === 0) {
			return;
		}
		const item = queue.shift();
		activeCount++;
		let result;
		try {
			result = item.fn();
		} catch (error) {
			activeCount--;
			item.reject(error);
			startNext();
			return;
		}
		Promise.resolve(result).then(
			value => {
				activeCount--;
				item.resolve(value);
				startNext();
			},
			error => {
				activeCount--;
				item.reject(error);
				startNext();
			}
		);
	}

	return entryFn => new Promise((resolve, reject) => {
		queue.push({ fn: entryFn, resolve, reject });
		startNext();
	});
