function sqlTag(strings, ...values) {
  let text = '';
  const resultValues = [];
  let counter = 0;

  function addScalar(v) {
    counter += 1;
    text += '$' + counter;
    resultValues.push(v);
  }

  for (let i = 0; i < strings.length - 1; i++) {
    text += strings[i];
    const value = values[i];

    if (value != null && typeof value === 'object' && !Array.isArray(value) &&
        typeof value.text === 'string' && Array.isArray(value.values)) {
      const offset = counter;
      counter += value.values.length;
      text += value.text.replace(/\$(\d+)/g, (_, d) => '$' + (Number(d) + offset));
      resultValues.push(...value.values);
    } else if (Array.isArray(value)) {
      text += '(';
      for (let j = 0; j < value.length; j++) {
        if (j > 0) text += ', ';
        addScalar(value[j]);
      }
      text += ')';
    } else {
      addScalar(value);
    }
  }

  text += strings[strings.length - 1];

  return { text, values: resultValues };
}

module.exports = sqlTag;
