type PickKeys<T extends object, K extends keyof T> = {
  [P in keyof T as P extends K ? P : never]: T[P];
};

type OmitKeys<T extends object, K extends keyof T> = {
  [P in keyof T as P extends K ? never : P]: T[P];
};

export function pick<T extends object, K extends keyof T>(
  obj: T,
  keys: readonly K[]
): PickKeys<T, K> {
  const result = {} as Record<PropertyKey, unknown>;
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      result[key] = obj[key];
    }
  }
  return result as unknown as PickKeys<T, K>;
}

export function omit<T extends object, K extends keyof T>(
  obj: T,
  keys: readonly K[]
): OmitKeys<T, K> {
  const result = {} as Record<PropertyKey, unknown>;
  const excluded = keys as unknown as readonly string[];
  for (const key of Object.keys(obj)) {
    if (!excluded.includes(key)) {
      result[key] = obj[key as keyof T];
    }
  }
  return result as unknown as OmitKeys<T, K>;
}
