type ExtractParams<Path extends string> =
  Path extends `${string}:${infer Param}/${infer Rest}`
    ? [Param, ...ExtractParams<Rest>]
    : Path extends `${string}:${infer Param}`
      ? [Param]
      : [];

type ParamsToObject<K extends readonly string[]> = {
  [P in K]: string;
};

type RouteFn<Path extends string> = [ExtractParams<Path>] extends [[]]
  ? () => string
  : (params: ParamsToObject<ExtractParams<Path>>) => string;

function interpolate(template: string, params: Record<string, string>): string {
  return template.replace(
    /:([a-zA-Z_][a-zA-Z0-9_]*)/g,
    (_match: string, name: string): string => {
      const value = params[name];
      if (value === undefined) {
        throw new Error(`Missing required route parameter "${name}"`);
      }
      return value;
    }
  );
}

export function defineRoutes<const Routes extends Record<string, string>>(
  routes: Routes
): { [K in keyof Routes]: RouteFn<Routes[K]> } {
  const out: Record<string, (params?: Record<string, string>) => string> = {};
  for (const key of Object.keys(routes)) {
    const template = routes[key];
    out[key] = (params?: Record<string, string>): string => interpolate(template, params ?? {});
  }
  return out as unknown as { [K in keyof Routes]: RouteFn<Routes[K]> };
}
