  if (isPlainObject(base) && isPlainObject(patch)) {
    const result: Record<string, unknown> = { ...base };
    for (const key of Object.keys(patch)) {
      const patchValue = patch[key];
      if (patchValue === undefined) continue; // leave the base value untouched
      result[key] = mergeValue(base[key], patchValue);
    }
    return result;
  }
  // Arrays are replaced wholesale; primitives and functions too.
  return patch === undefined ? base : patch;
}

